/** Real-photo case gallery and per-case dashboard (photo, measurements, comparison, trend). */
import { useEffect, useState } from 'preact/hooks';
import { STILL_BANDS_MM, type StillExpression } from '../../core';
import { CASES, EXPRESSION_LABEL, caseById } from '../../cases/library';
import { actions, useApp } from '../../data/store';
import type { PhotoRecord } from '../../data/types';
import { AppBar, Notice } from '../components/common';
import {
  AlignedCompare,
  Attribution,
  PhotoMeasure,
  PhotoTimeline,
  RegionRows,
  StillTrend,
  sourceOf,
  trendSummary,
} from '../components/photo';
import { Icon } from '../icons';
import { SIDE_LABEL } from '../labels';

export function useCaseLoader(caseId: string | null | undefined) {
  const { photos } = useApp();
  const records = photos.filter((p) => p.caseId === caseId);
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const load = async () => {
    if (!caseId) return;
    setError(null);
    setBusy('준비 중…');
    try {
      await actions.loadCase(caseId, (d, t, m) => setBusy(`${m} (${Math.min(d + 1, t)}/${t})`));
    } catch (e) {
      setError(`사진 분석에 실패했습니다: ${String(e).slice(0, 120)}`);
    } finally {
      setBusy(null);
    }
  };
  return { records, busy, error, load };
}

export function CaseGallery() {
  const { photos } = useApp();
  return (
    <>
      <AppBar title="실제 사진 사례" sub="공개 라이선스 안면마비 사진" onBack />
      <main class="main">
        <div class="card tight">
          <Notice>
            <span class="small">
              Wikimedia Commons에 공개 라이선스(CC BY-SA 4.0)로 올라온 실제 환자 사진입니다. 앱은 사진을 기기 안에서 분석해 좌우 차이를
              계산합니다. 수치는 예시 분석값이며 해당 인물의 진료 기록이 아닙니다.
            </span>
          </Notice>
        </div>
        {CASES.map((c) => {
          const n = photos.filter((p) => p.caseId === c.id).length;
          return (
            <a class="card case-card" href={`#/case/${c.id}`}>
              <img src={c.photos[c.photos.length - 1]!.file} alt="" loading="lazy" />
              <div class="stack" style={{ gap: '4px' }}>
                <h3>{c.title}</h3>
                <div class="small ink2">{c.subtitle}</div>
                <div class="row wrap">
                  <span class="chip">마비 쪽 {SIDE_LABEL[c.affectedSide]}</span>
                  <span class={`chip ${n ? 'good' : ''}`}>{n ? '분석됨' : '분석 전'}</span>
                </div>
              </div>
            </a>
          );
        })}
      </main>
    </>
  );
}

export function CaseProgress({ records }: { records: PhotoRecord[] }) {
  const analysed = records.filter((r) => r.analysis);
  const dated = analysed.filter((r) => r.day !== null);
  const summary = trendSummary(records);
  // Default to the same task at its first and last time point (e.g. first smile vs day-19 smile).
  const lead = summary[0];
  const atDay = (day: number | undefined) =>
    day === undefined ? undefined : dated.find((r) => r.day === day && r.expression !== 'rest' && r.expression !== 'eyeClose');
  const [from, setFrom] = useState(atDay(lead?.first.day)?.id ?? dated[0]?.id ?? analysed[0]?.id ?? '');
  const [to, setTo] = useState(atDay(lead?.last.day)?.id ?? dated[dated.length - 1]?.id ?? analysed[analysed.length - 1]?.id ?? '');
  const before = analysed.find((r) => r.id === from);
  const after = analysed.find((r) => r.id === to);
  const pick = (value: string, set: (v: string) => void, label: string) => (
    <label class="field grow">
      <span class="xsmall">{label}</span>
      <select class="input" value={value} onChange={(e) => set((e.target as HTMLSelectElement).value)}>
        {analysed.map((r) => (
          <option value={r.id}>{r.label}</option>
        ))}
      </select>
    </label>
  );
  return (
    <>
      {summary.length > 0 && (
        <div class="card">
          <h3>같은 과제끼리 비교한 경과</h3>
          <div class="tiles">
            {summary.map((s) => (
              <div class="tile">
                <span class="label">{s.label} 좌우 차이</span>
                <span class="value tabular">
                  {s.first.mm.toFixed(1)}→{s.last.mm.toFixed(1)}
                  <small>mm</small>
                </span>
                <span class="xsmall muted">
                  {s.first.day}일째 → {s.last.day}일째
                </span>
              </div>
            ))}
          </div>
          <StillTrend records={records} />
          <p class="xsmall muted">
            날마다 찍은 표정이 달라, 같은 과제(웃기·이마 올리기·눈 감기)의 사진끼리만 선으로 잇습니다. 값은 마비 쪽이 불리한 방향의 좌우
            차이이며 낮을수록 대칭입니다. {STILL_BANDS_MM[0]}mm 미만은 정상 범위로 봅니다(잠정 기준).
          </p>
        </div>
      )}
      {before && after && (
        <div class="card">
          <h3>사진 전후 비교</h3>
          <div class="row">
            {pick(from, setFrom, '왼쪽')}
            {pick(to, setTo, '오른쪽')}
          </div>
          <AlignedCompare before={before} after={after} />
        </div>
      )}
    </>
  );
}

export function PhotoPanel({ record }: { record: PhotoRecord }) {
  const { integrity } = useApp();
  const [contours, setContours] = useState(false);
  const a = record.analysis;
  const src = sourceOf(record);
  return (
    <div class="card">
      <div class="card-head">
        <div>
          <h3>{record.label}</h3>
          <div class="xsmall muted">
            {EXPRESSION_LABEL[record.expression as StillExpression]}
            {record.takenAt ? ` · 촬영 ${record.takenAt}` : ''}
          </div>
        </div>
        {a && (
          <button class="btn sm ghost" onClick={() => setContours(!contours)} aria-pressed={contours}>
            <Icon name="face" /> 윤곽 {contours ? '끄기' : '보기'}
          </button>
        )}
      </div>
      <PhotoMeasure record={record} contours={contours} />
      {src && <Attribution source={src} />}
      {record.note && (
        <Notice>
          <span class="small">{record.note}</span>
        </Notice>
      )}
      {!a ? (
        <Notice tone="warn">
          <span class="small">이 사진에서 얼굴을 찾지 못해 측정하지 않았습니다.</span>
        </Notice>
      ) : (
        <>
          <div class="row between">
            <span class="small ink2">
              이 표정의 대칭도 <span class="est">추정</span>
            </span>
            <b class="tabular" style={{ fontSize: '22px' }}>
              {a.symmetryIndex ?? '–'}
              <small class="muted" style={{ fontSize: '13px' }}>
                {a.symmetryIndex !== null ? ' / 100' : ''}
              </small>
            </b>
          </div>
          <RegionRows a={a} />
          <div class="xsmall muted">
            주황 = 마비 쪽, 파랑 = 건강한 쪽. 짧은 가로 막대는 눈썹·입꼬리 높이, 흰 선은 동공선과 정중선입니다. 흐리게 표시된 부위는 이
            표정에서 주로 보는 부위가 아닙니다.
          </div>
          {a.suggestedAffectedSide && a.suggestedAffectedSide !== a.affectedSide && (
            <Notice tone="warn">
              <span class="small">이 사진에서는 반대쪽이 더 약해 보입니다. 촬영 방향(좌우 반전)이나 표정을 확인하세요.</span>
            </Notice>
          )}
          {a.quality.issues.length > 0 && (
            <Notice tone="warn">
              <span class="small">
                촬영 조건 경고:{' '}
                {a.quality.issues
                  .map(
                    (i) =>
                      ({
                        yaw: '고개 돌아감',
                        pitch: '고개 숙임/듦',
                        roll: '머리 기울어짐',
                        tooFar: '얼굴이 작음',
                        outOfFrame: '얼굴 일부 잘림',
                        dark: '어두움',
                        bright: '너무 밝음',
                        unevenLight: '한쪽 조명',
                        noFace: '얼굴 없음',
                      })[i],
                  )
                  .join(', ')}
                . 수치의 정확도가 낮을 수 있습니다.
              </span>
            </Notice>
          )}
          <details>
            <summary class="xsmall ink2">측정 세부값과 기술 정보</summary>
            <table class="data" style={{ marginTop: '6px' }}>
              <thead>
                <tr>
                  <th>mm</th>
                  <th>환자 오른쪽</th>
                  <th>환자 왼쪽</th>
                </tr>
              </thead>
              <tbody>
                {(
                  [
                    ['동공→눈썹 높이', 'browHeight'],
                    ['눈 뜬 높이', 'fissure'],
                    ['동공→윗눈꺼풀(MRD1)', 'mrd1'],
                    ['동공선→입꼬리', 'commissureHeight'],
                    ['정중선→입꼬리', 'commissureLateral'],
                    ['동공선→콧방울', 'alaHeight'],
                  ] as const
                ).map(([name, k]) => (
                  <tr>
                    <td>{name}</td>
                    <td>{a.sides.right[k].toFixed(1)}</td>
                    <td>{a.sides.left[k].toFixed(1)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div class="xsmall ink2 stack" style={{ gap: '2px', marginTop: '6px' }}>
              <div>
                척도 {a.scaleSource === 'iris' ? `홍채 기준 (IPD ${a.mmPerUnit.toFixed(1)}mm)` : `표준 동공간거리 ${a.mmPerUnit}mm 가정`} ·
                입꼬리 기울기 {a.commissureTiltDeg.toFixed(1)}° · 머리 자세 좌우 {a.quality.pose.yaw.toFixed(0)}° / 상하{' '}
                {a.quality.pose.pitch.toFixed(0)}°
              </div>
              <div>
                {a.algorithm.id} v{a.algorithm.version} · {record.engine?.runtime} · {record.engine?.delegate}
              </div>
              <div class="mono">record sha256 {record.integrity.hash}</div>
              <div>{integrity[record.id] ? '무결성 확인됨' : '무결성 오류'}</div>
            </div>
          </details>
        </>
      )}
    </div>
  );
}

export function CaseDashboard({ id }: { id: string }) {
  const c = caseById(id);
  const { records, busy, error, load } = useCaseLoader(id);
  const [sel, setSel] = useState<string>('');
  const selected = records.find((r) => r.id === sel) ?? records[records.length - 1];
  useEffect(() => {
    if (records.length && !records.some((r) => r.id === sel)) setSel(records[records.length - 1]!.id);
  }, [records.length]);
  if (!c) {
    return (
      <>
        <AppBar title="사례" onBack />
        <main class="main">
          <div class="card">사례를 찾을 수 없습니다.</div>
        </main>
      </>
    );
  }
  const sideVotes = records.filter((r) => r.analysis?.suggestedAffectedSide);
  const agree = sideVotes.filter((r) => r.analysis!.suggestedAffectedSide === c.affectedSide).length;
  return (
    <>
      <AppBar title={c.title} sub={c.subtitle} onBack />
      <main class="main">
        <div class="card tight">
          <p class="small">{c.description}</p>
          <div class="row wrap">
            <span class="chip">벨마비</span>
            <span class="chip">마비 쪽 {SIDE_LABEL[c.affectedSide]}</span>
            {sideVotes.length > 0 && (
              <span class={`chip ${agree === sideVotes.length ? 'good' : 'warn'}`}>
                측정상 약한 쪽 일치 {agree}/{sideVotes.length}
              </span>
            )}
          </div>
          <p class="xsmall muted">{c.sideNote}</p>
        </div>

        {records.length === 0 ? (
          <div class="card">
            <p class="small ink2">
              사진 {c.photos.length}장을 기기 안에서 분석합니다. 처음에는 얼굴 인식 모델을 불러오느라 몇 초 걸립니다.
            </p>
            <button class="btn primary block" disabled={!!busy} onClick={load}>
              <Icon name="face" /> {busy ?? '사진 분석하기'}
            </button>
            {error && (
              <Notice tone="danger">
                <span class="small">{error}</span>
              </Notice>
            )}
          </div>
        ) : (
          <>
            <PhotoTimeline records={records} selected={selected?.id ?? ''} onSelect={setSel} />
            {selected && <PhotoPanel record={selected} />}
            <CaseProgress records={records} />
            <button class="btn ghost block" disabled={!!busy} onClick={load}>
              {busy ?? '다시 분석하기'}
            </button>
          </>
        )}
        <p class="xsmall muted center">공개 사진 예시 분석 · 진단 목적이 아닙니다 · 사진 라이선스는 각 사진 아래 표기</p>
      </main>
    </>
  );
}
